gti(){return"\u0aa4\u0aae\u0ac7 12 \u0a95\u0ab2\u0abe\u0a95\u0aa5\u0ac0 \u0ab5\u0aa7\u0ac1 \u0a95\u0abe\u0aae \u0a95\u0ab0\u0acd\u0aaf\u0ac1\u0a82 \u0a9b\u0ac7. \u0aa4\u0aae\u0abe\u0ab0\u0acb \u0aaa\u0a82\u0a9a \u0ab0\u0abf\u0ab5\u0acd\u0aaf\u0ac1 \u0aae\u0abe\u0a9f\u0ac7 \u0ab8\u0aac\u0aae\u0abf\u0a9f \u0a95\u0ab0\u0ab5\u0abe\u0aae\u0abe\u0a82 \u0a86\u0ab5\u0ab6\u0ac7."},
tk(a){return a+" \u0aab\u0a95\u0acd\u0aa4 4 PM \u0aa5\u0ac0 8 PM \u0ab5\u0a9a\u0acd\u0a9a\u0ac7 \u0a9c \u0aae\u0a82\u0a9c\u0ac2\u0ab0 \u0a9b\u0ac7. \u0aa4\u0aae\u0abe\u0ab0\u0acb \u0aaa\u0a82\u0a9a \u0ab0\u0abf\u0ab5\u0acd\u0aaf\u0ac1 \u0aae\u0abe\u0a9f\u0ac7 \u0ab8\u0aac\u0aae\u0abf\u0a9f \u0a95\u0ab0\u0ab5\u0abe\u0aae\u0abe\u0a82 \u0a86\u0ab5\u0ab6\u0ac7."},
gtR(){return"\u0a95\u0a82\u0a88\u0a95 \u0a96\u0acb\u0a9f\u0ac1\u0a82 \u0aa5\u0aaf\u0ac1\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0aaf\u0aa4\u0acd\u0aa8 \u0a95\u0ab0\u0acb."},
gtT(){return"\u0ab0\u0abf\u0a95\u0acd\u0ab5\u0ac7\u0ab8\u0acd\u0a9f \u0ab5\u0ac7\u0ab0\u0abf\u0aab\u0abe\u0aaf \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0abe\u0aaf\u0acb \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0aaa\u0acd\u0ab0\u0aaf\u0aa4\u0acd\u0aa8 \u0a95\u0ab0\u0acb."},
gtp(){return"\u0a88\u0aae\u0ac7\u0ab2 \u0a85\u0aa5\u0ab5\u0abe \u0aab\u0acb\u0aa8 \u0aa8\u0a82\u0aac\u0ab0 \u0a9c\u0ab0\u0ac2\u0ab0\u0ac0 \u0a9b\u0ac7."},
gtn(){return"\u0aae\u0abe\u0aa8\u0acd\u0aaf \u0a88\u0aae\u0ac7\u0ab2 \u0a85\u0aa5\u0ab5\u0abe 10-\u0a85\u0a82\u0a95\u0aa8\u0acb \u0aab\u0acb\u0aa8 \u0aa8\u0a82\u0aac\u0ab0 \u0aa6\u0abe\u0a96\u0ab2 \u0a95\u0ab0\u0acb."},
gtr(){return"\u0a85\u0aae\u0ac7 \u0aa4\u0aae\u0aa8\u0ac7 \u0ab8\u0abe\u0a87\u0aa8 \u0a87\u0aa8 \u0a95\u0ab0\u0ac0 \u0ab6\u0a95\u0acd\u0aaf\u0abe \u0aa8\u0ab9\u0ac0\u0a82. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aa4\u0aae\u0abe\u0ab0\u0abe \u0ab8\u0a82\u0ab8\u0acd\u0aa5\u0abe\u0aa8\u0abe \u0a8f\u0aa1\u0aae\u0abf\u0aa8\u0abf\u0ab8\u0acd\u0a9f\u0acd\u0ab0\u0ac7\u0a9f\u0ab0\u0aa8\u0acb \u0ab8\u0a82\u0aaa\u0ab0\u0acd\u0a95 \u0a95\u0ab0\u0acb."},
gtu(){return"\u0aa4\u0aae\u0abe\u0ab0\u0ac0 \u0ab8\u0a82\u0ab8\u0acd\u0aa5\u0abe\u0aa8\u0ac1\u0a82 \u0ab8\u0aac\u0ab8\u0acd\u0a95\u0acd\u0ab0\u0abf\u0aaa\u0acd\u0ab6\u0aa8 \u0ab8\u0aae\u0abe\u0aaa\u0acd\u0aa4 \u0aa5\u0aaf\u0ac1\u0a82 \u0a9b\u0ac7. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aa4\u0aae\u0abe\u0ab0\u0abe \u0a8f\u0aa1\u0aae\u0abf\u0aa8\u0abf\u0ab8\u0acd\u0a9f\u0acd\u0ab0\u0ac7\u0a9f\u0ab0\u0aa8\u0acb \u0ab8\u0a82\u0aaa\u0ab0\u0acd\u0a95 \u0a95\u0ab0\u0acb."},
gtt(){return"\u0aa4\u0aae\u0abe\u0ab0\u0ac1\u0a82 \u0ab8\u0ac7\u0ab6\u0aa8 \u0ab8\u0aae\u0abe\u0aaa\u0acd\u0aa4 \u0aa5\u0aaf\u0ac1\u0a82 \u0a9b\u0ac7. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0ab8\u0abe\u0a87\u0aa8 \u0a87\u0aa8 \u0a95\u0ab0\u0acb."},
gtq(){return"\u0aa4\u0aae\u0ac7 \u0ab8\u0aab\u0ab3\u0aa4\u0abe\u0aaa\u0ac2\u0ab0\u0acd\u0ab5\u0a95 \u0ab2\u0acb\u0a97\u0a86\u0a89\u0a9f \u0aa5\u0aaf\u0abe \u0a9b\u0acb."},
