gva(){return"\u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 6 \u0a85\u0a82\u0a95 \u0aa6\u0abe\u0a96\u0ab2 \u0a95\u0ab0\u0acb."},
gvb(){return"OTP \u0ab8\u0aae\u0abe\u0aaa\u0acd\u0aa4 \u0aa5\u0aaf\u0acb. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aab\u0ab0\u0ac0 \u0ab5\u0abf\u0aa8\u0a82\u0aa4\u0ac0 \u0a95\u0ab0\u0acb."},
gvc(){return"\u0aa4\u0aae\u0ac7 \u0aa6\u0abe\u0a96\u0ab2 \u0a95\u0ab0\u0ac7\u0ab2\u0acb \u0a95\u0acb\u0aa1 \u0a85\u0aae\u0abe\u0aa8\u0acd\u0aaf \u0a9b\u0ac7."},
gvf(){return"\u0aa4\u0aae\u0abe\u0ab0\u0ac1\u0a82 \u0ab5\u0ac7\u0ab0\u0abf\u0aab\u0abf\u0a95\u0ac7\u0ab6\u0aa8 \u0ab8\u0ac7\u0ab6\u0aa8 \u0ab8\u0aae\u0abe\u0aaa\u0acd\u0aa4 \u0aa5\u0aaf\u0ac1\u0a82 \u0a9b\u0ac7. \u0a95\u0ac3\u0aaa\u0abe \u0a95\u0ab0\u0ac0 \u0aa8\u0ab5\u0acb \u0a95\u0acb\u0aa1 \u0aae\u0a82\u0a97\u0abe\u0ab5\u0acb."},
